
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_chachiyo_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_chachiyo", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.043518807106300e-02, -5.948449408562295e-02, -5.812909119460584e-02, -5.620434445797656e-02, -5.348723398161875e-02, -4.968682939706529e-02, -4.445315282257482e-02, -3.745277952067961e-02, -2.866004683182492e-02, -1.927441948504836e-02, -1.437726764270287e-02, -3.609637128707555e-02, -4.443517913100061e-02, -3.056585741138098e-02, -1.593760447841078e-02, -4.233228188316864e-03, -1.177812387047934e-04, -8.131463141345981e-11, -5.823726837059539e-54, -0.000000000000000e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


